"use client";

import { useEffect, useState } from "react";
import PreviewFrame from "@/components/builder/PreviewFrame";

export default function BuilderClient({ projectId }: { projectId: string }) {
  const [previewCode, setPreviewCode] = useState("");

  useEffect(() => {
    if (!projectId) return;

    fetch("/api/dev/preview?projectId=" + projectId)
      .then((r) => r.json())
      .then((d) => {
        if (d.ok) {
          setPreviewCode(d.code);
        } else {
          console.error("Preview error:", d.error);
        }
      });
  }, [projectId]);

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* LEFT SIDE */}
      <div style={{ width: "50%", borderRight: "1px solid #222" }}>
        <div style={{ padding: 20 }}>Editor</div>
      </div>

      {/* RIGHT SIDE → REAL PREVIEW */}
      <div style={{ width: "50%", background: "#fff" }}>
        {previewCode ? (
          <PreviewFrame code={previewCode} />
        ) : (
          <div style={{ padding: 20 }}>Loading preview...</div>
        )}
      </div>
    </div>
  );
}
EOF

